interface.definition:
a!localVariables(
  local!sumarizadas: index(ri!sumarizadas, "body", {}),
  local!vivienda2: index(ri!vivienda, "body", {}),
  local!totales: index(ri!totales, "body", {}),
  local!docId_int,
  local!intentoDescarga: false,
  local!mensajeRespuesta: "",
  local!nombreDocumento: "",
  local!show:false,
  local!vivienda:if(a!isNullOrEmpty(local!vivienda2),{totalWithCredit:0,totalWithoutCredit:0},local!vivienda2),
  local!indexOrd: a!flatten(
    wherecontains(
      268,
      tointeger(
        index(
          local!sumarizadas[1],
          "contributionRelease",
          "contributionRelease",
          "id",
          0
        )
      )
    )
  ),
  local!indexAcl: wherecontains(
    269,
    tointeger(
      index(
        local!sumarizadas[1],
        "contributionRelease",
        "contributionRelease",
        "id",
        0
      )
    )
  ),
  local!ordinarias: index(
    local!sumarizadas,
    "contributionRelease",
    "contributionRelease",
    "summarizedNumber",
    "summarizedNumber",
    local!indexOrd,
    {}
  ),
  local!aclaraciones: index(
    local!sumarizadas,
    "contributionRelease",
    "contributionRelease",
    "summarizedNumber",
    "summarizedNumber",
    local!indexAcl,
    {}
  ),
  local!idLiberacion: tointeger(
    index(
      local!sumarizadas,
      "contributionRelease",
      "contributionRelease",
      "id",
      0
    )
  ),
  local!cleanVivienda: #"SYSTEM_SYSRULES_forEach"(
    items: index(
      local!vivienda,
      "housingAmounts",
      "housingAmounts",
      {}
    ),
    expression: if(
      todecimal(fv!item.amountTotal) <> 0,
      fv!item,
      {}
    )
  ),
  local!showCalcMovs: false,
  local!showGenerarArchivo:false,
  local!showInstanceDetail: true,
  local!showPopWarning: false,
  local!reloadBrands: false,
  local!brandsCoexistence: a!refreshVariable(
    value: #"1a05f799-cf19-4ce1-90d5-aaf772921e48"(
      folioNumber: index(ri!archivo, "folio", null),
      brandStatus: 0,
      page: 1,
      limit: 10
    ).result.headers,
    refreshOnVarChange: local!reloadBrands
  ),
  /*local!brandsCoexistence: {
    Date: today()
    totalrecords: 10
  },*/
  local!messageCoexistence,
  local!activeMarcas: false,
  local!vistaModalRechazarFolio: false,
  local!existBitacora: 
  if(a!isNullOrEmpty(ri!request),1,#"SYSTEM_SYSRULES_queryRecordType_v2"(
    recordType: #"urn:appian:record-type:v1:2e875f37-a45c-4931-b48c-bcbd5e117aba",
    filters: #"SYSTEM_SYSRULES_queryFilter"(
      field: #"urn:appian:record-field:v1:2e875f37-a45c-4931-b48c-bcbd5e117aba/c6c64a7e-8d1d-491d-9ed8-b477f1266091",
      operator: "=",
      value: tointeger(ri!request.idInstancia)
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1)
  ).data[#"urn:appian:record-field:v1:2e875f37-a45c-4931-b48c-bcbd5e117aba/c6c64a7e-8d1d-491d-9ed8-b477f1266091"]),
  local!AceptBitacora: if(
    a!isNullOrEmpty(local!existBitacora),
    true,
    false
  ),
  local!flagExportarCuentas: false,
  local!consultaDoc:a!refreshVariable(
    value: if(
      and(local!intentoDescarga,local!mensajeRespuesta="Incompleto"),
      #"f74c3fea-f7cf-4af7-8537-3a66751225ec"(
        folio: index(ri!archivo, "folio", null),
        /*IMPORTANTE CAMBIAR A LA OPCION DE LA DESCARAGA*/
        option: 7,
        idInstancia: index(ri!request, "idInstancia", null),
      ),
      null
    ),
    refreshInterval: 0.5
  ),
  {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_boxLayout"(
                  label: "Notificacion",
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {
                        "Al ",
                        #"SYSTEM_SYSRULES_richTextItem_v1"(text: { "Aceptar " }, style: { "STRONG" }),
                        #"_a-0000ee45-8509-8000-9bb1-011c48011c48_327358"
                      }
                    ),
                    #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                      buttons: {
                        #"SYSTEM_SYSRULES_buttonWidget_v1"(
                          label: "Aceptar",
                          saveInto: {
                            #"SYSTEM_SYSRULES_startProcess"(
                              processModel: #"_a-0000ee45-8509-8000-9bb1-011c48011c48_325133",
                              processParameters: {
                                request: ri!request,
                                usuarioCreacion: tostring(loggedInUser()),
                                isBitacora:true
                              }
                            ),
                            a!save(local!AceptBitacora, false)
                          },
                          loadingIndicator: true,
                          submit: false,
                          style: "SOLID",
                          size: "SMALL",
                          color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774"
                        )
                      },
                      align: "END"
                    )
                  },
                  style: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",

                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(),

          }
        )
      },
      showWhen: local!AceptBitacora
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: {
        #"SYSTEM_SYSRULES_sectionLayout_v1"(
          contents: {
            #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_90033"(
              TituloTexto: "Revisión de Cifras Control",
              showWhen: local!showInstanceDetail
            ),
            #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_sectionLayout_v1"(
                      marginAbove: "EVEN_MORE",
                      marginBelow: "EVEN_MORE"
                    ),
                    #"SYSTEM_SYSRULES_sectionLayout_v1"(
                      contents: {
                        #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_205413"(showWhen: local!showPopWarning),
                        /*rule!NCI_PantallaDeAviso(*/
                        /*header_txt:cons!NCI_POOL_MSG_FOR_TASKS_TXT_LIST[1],*/
                        /*message_txt: cons!NCI_POOL_MSG_FOR_TASKS_TXT_LIST[2],*/
                        /*showWhen: local!showPopWarning*/
                        /*),*/
                        #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_100254"(
                          label_txt: "Ingrese la fecha para calcular movimientos",
                          action_int: ri!action_int,
                          showWhen: local!showCalcMovs,
                          fechaGenMovs: ri!fechaGeneracionMovimientos,
                          valorAccion: ri!valoresAccion,
                          subproceso_int: ri!archivo.subproceso.id
                        ),
                        #"_a-0000ede3-bd80-8000-9baf-011c48011c48_288069"(
                          label_txt: "Resumen de Archivo de Respuesta",
                          action_int: ri!action_int,
                          showWhen: local!showGenerarArchivo,
                          folio_txt: ri!archivo.folio,
                          processID_txt: ri!archivo.proceso.id,
                          subprocessID_txt: ri!archivo.subproceso.id,
                        ),
                        #"SYSTEM_SYSRULES_sectionLayout_v1"(
                          contents: {
                            #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_256027"(text_in: local!messageCoexistence, close: local!activeMarcas)
                          },
                          showWhen: if(local!activeMarcas, true, false)
                        ),

                        #"SYSTEM_SYSRULES_sectionLayout_v1"(
                          contents: {
                            #"SYSTEM_SYSRULES_columnsLayout"(
                              columns: {
                                #"SYSTEM_SYSRULES_columnLayout"(),
                                #"SYSTEM_SYSRULES_columnLayout"(
                                  contents: {
                                    #"SYSTEM_SYSRULES_boxLayout"(
                                      label:"Rechazar Folio",
                                      contents: {
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                                          labelPosition: "COLLAPSED",
                                          value: {
                                            "¿",
                                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: { "Confirma" }, style: { "STRONG" }),
                                            " el rechazo de folio?"
                                          }
                                        ),

                                        #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                                          buttons: {
                                            #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                              label: "Aceptar",
                                              saveInto: {
                                                a!save(ri!action_int, 2),
                                                a!save(local!vistaModalRechazarFolio, false),
                                              },
                                              submit: true,
                                              style: "SOLID",
                                              color:#"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774"
                                            ),
                                            #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                              label: "Cancelar",
                                              saveInto: {
                                                a!save(local!vistaModalRechazarFolio, false)
                                              },
                                              style: "OUTLINE",
                                              color:#"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774"
                                            )
                                          },
                                          align: "END"
                                        )
                                      },
                                      style: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",

                                    )
                                  }
                                ),
                                #"SYSTEM_SYSRULES_columnLayout"(),
                              }
                            )
                          },
                          showWhen: local!vistaModalRechazarFolio
                        )
                      }
                    )
                  },
                  showWhen: or(
                    local!showPopWarning,
                    local!showCalcMovs,
                    local!showGenerarArchivo,
                    local!activeMarcas,
                    local!vistaModalRechazarFolio
                  )
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_boxLayout"(
                      label: "Información de Cifras Control Generadas",
                      contents: {
                        #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_columnsLayout"(
                              columns: {
                                #"SYSTEM_SYSRULES_columnLayout"(
                                  contents: {
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Folio:  ",
                                        color: "#000000",
                                        style: "STRONG"
                                      ),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: ri!archivo.folio, color: "#000000")
                                    },
                                    marginBelow: "NONE"
                                  ),                                  
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Nombre:  ",
                                        color: "#000000",
                                        style: "STRONG"
                                      ),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: ri!archivo.nombreArchSinExtension,
                                        color: "#000000"
                                      )
                                    },
                                    marginBelow: "NONE"
                                  ),
                                  },
                                  width: "2X"
                                ),
                                #"SYSTEM_SYSRULES_columnLayout"(
                                  contents: {
                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                      value: {
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                                          text: "Proceso:  ",
                                          color: "#000000",
                                          style: "STRONG"
                                        ),
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                                          text: ri!archivo.proceso.descripcion,
                                          color: "#000000"
                                        )
                                      },
                                      marginBelow: "NONE"
                                    ),
                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                      value: {
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Subproceso: ", style: "STRONG"),
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(text: ri!archivo.subproceso.descripcion)
                                      },
                                      marginBelow: "NONE"
                                    ),






                                  }
                                ),
                                #"SYSTEM_SYSRULES_columnLayout"(
                                  contents: {
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Estatus:  ",
                                        color: "#000000",
                                        style: "STRONG"
                                      ),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: "EN EJECUCIÓN", color: "#000000")
                                    },
                                    marginBelow: "NONE"
                                  ),
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Fecha Recepción:  ",
                                        color: "#000000",
                                        style: "STRONG"
                                      ),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: text(ri!archivo.fechaRecepcion, "dd/MM/yyyy"),
                                        color: "#000000"
                                      )
                                    },
                                    marginBelow: "NONE"
                                  )
                                  }
                                ),
                                #"SYSTEM_SYSRULES_columnLayout"(
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Fecha Último Estatus:  ",
                                        style: "STRONG"
                                      ),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: text(
                                          ri!archivo.fechaUltimoEstatus,
                                          "dd/MM/yyyy"
                                        )
                                      )
                                    },
                                    marginBelow: "NONE"
                                  )
                                )


                              },
                              marginBelow: "NONE"
                            ),
                          },
                          shape: "ROUNDED",
                          showBorder: true
                        )

                      },
                      style: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774",
                      showBorder: false

                    ),
                    #"SYSTEM_SYSRULES_boxLayout"(
                      label: "Reporte Registros",
                      contents: {
                        a!localVariables(
                          #"SYSTEM_SYSRULES_columnsLayout"(
                            columns: {
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: #"SYSTEM_SYSRULES_gridLayout"(
                                  headerCells: {
                                    #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Siefore", align: "CENTER"),
                                    #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Registros", align: "CENTER")
                                  },
                                  rows: {
                                    #"SYSTEM_SYSRULES_gridRowLayout"(
                                      contents: {
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                            text: "Total Registros",
                                            color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375"
                                          ),
                                          align: "CENTER"
                                        ),
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(

                                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(

                                            color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375",
                                            text: sum(
                                              index(
                                                local!totales,
                                                "registers",
                                                "acceptedRegisters",
                                                0
                                              )
                                            )
                                          ),
                                          align: "CENTER"
                                        )
                                      }
                                    ),
                                    #"SYSTEM_SYSRULES_forEach"(
                                      items: index(local!totales, "registers", {}),
                                      expression: #"SYSTEM_SYSRULES_gridRowLayout"(
                                        contents: {
                                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: fv!item.sieforeDescription),
                                            align:"CENTER",
                                          ),
                                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: fv!item.acceptedRegisters),
                                            align:"CENTER",
                                          )
                                        }
                                      )
                                    ),
                                    #"SYSTEM_SYSRULES_gridRowLayout"(
                                      contents: {
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Rechazados"),
                                          align:"CENTER"
                                        ),
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                                          align:"CENTER",
                                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                            text: sum(
                                              index(
                                                local!totales,
                                                "registers",
                                                "rejectedRegisters",
                                                0
                                              )
                                            )
                                          )
                                        )
                                      }
                                    )
                                  }
                                ),
                                width: "MEDIUM"
                              )
                            }

                          )
                        )

                      },
                      style: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774",
                      showBorder: false

                    ),
                    #"SYSTEM_SYSRULES_boxLayout"(
                      label: "Cifras Control",
                      contents: {
                        a!localVariables(
                          local!selectedTab: 1,
                          {
                            #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                              buttons: {
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Ordinarias",
                                  saveInto: if(
                                    local!selectedTab = 1,
                                    {},
                                    a!save(local!selectedTab, 1)
                                  ),
                                  size: "SMALL",
                                  width: "MINIMIZE",
                                  style: if(local!selectedTab = 1, "SOLID", "SOLID"),
                                  color: if(
                                    local!selectedTab = 1,
                                    #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",
                                    #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_8114"
                                  )
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Aclaraciones",
                                  saveInto: if(
                                    local!selectedTab = 2,
                                    {},
                                    a!save(local!selectedTab, 2)
                                  ),
                                  size: "SMALL",
                                  width: "MINIMIZE",
                                  style: if(local!selectedTab = 2, "SOLID", "SOLID"),
                                  color: if(
                                    local!selectedTab = 2,
                                    #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",
                                    #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_8114"
                                  )
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Vivienda",
                                  saveInto: if(
                                    local!selectedTab = 3,
                                    {},
                                    a!save(local!selectedTab, 3)
                                  ),
                                  size: "SMALL",
                                  width: "MINIMIZE",
                                  style: if(local!selectedTab = 3, "SOLID", "SOLID"),
                                  color: if(
                                    local!selectedTab = 3,
                                    #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",
                                    #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_8114"
                                  )
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Totales",
                                  saveInto: if(
                                    local!selectedTab = 4,
                                    {},
                                    a!save(local!selectedTab, 4)
                                  ),
                                  size: "SMALL",
                                  width: "MINIMIZE",
                                  style: if(local!selectedTab = 4, "SOLID", "SOLID"),
                                  color: if(
                                    local!selectedTab = 4,
                                    #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",
                                    #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_8114"
                                  )
                                )
                              }
                            ),
                            if(
                              local!selectedTab = 1,
                              {
                                #"SYSTEM_SYSRULES_boxLayout"(
                                  label: "Cifras Control Ordinarias",
                                  contents: {
                                    #"SYSTEM_SYSRULES_sectionLayout_v1"(
                                      label: "",
                                      contents: {
                                        if(
                                          contains(local!idLiberacion, 268),
                                          #"SYSTEM_SYSRULES_gridLayout"(
                                            emptyGridMessage: "No se encontraron registros",
                                            headerCells: {
                                              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(
                                                label: "Tipo de Aportación",
                                                align: "CENTER"
                                              ),
                                              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Total Aceptado", align: "CENTER"),
                                              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Total Rechazado", align: "CENTER"),
                                              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Total Archivo", align: "CENTER")
                                            },
                                            rows: {
                                              #"SYSTEM_SYSRULES_forEach"(
                                                items: index(local!ordinarias, 1, {}),
                                                expression: #"SYSTEM_SYSRULES_gridRowLayout"(
                                                  contents: {
                                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                                      value: fv!item.amountConcept.description,
                                                      align: "CENTER"
                                                    ),
                                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                                        text: #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_10856"(
                                                          nStr: fixed(fv!item.acceptedAmount, 2, true)
                                                        ).formatearNumero2,
                                                        color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375"

                                                      ),
                                                      align: "RIGHT"
                                                    ),
                                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                                        text: #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_10856"(
                                                          nStr: fixed(fv!item.rejectedAmount, 2, true)
                                                        ).formatearNumero2,
                                                        color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375"

                                                      ),
                                                      align: "RIGHT"
                                                    ),
                                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                                        text: #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_10856"(nStr: fixed(fv!item.amountTotal, 2, true)).formatearNumero2,
                                                        color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375"

                                                      ),
                                                      align: "RIGHT"
                                                    )
                                                  }
                                                )
                                              ),
                                              #"SYSTEM_SYSRULES_gridRowLayout"(
                                                contents: {
                                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                                      text: "Total",
                                                      color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375",
                                                      style: "PLAIN"
                                                    ),
                                                    align: "CENTER"

                                                  ),
                                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                                      text: #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_10856"(
                                                        nStr: fixed(
                                                          sum(
                                                            todecimal(local!ordinarias.acceptedAmount)
