                    #"d8c51b1b-47f4-494a-a360-e31b8c316406"(
                      docId_int: local!docId_int,
                      /*IMPORTANTE CAMBIAR A COMO ESTABA EN LA DESCARAGA*/
                      nombre: concat(
                        "Cifras_Control_",
                        index(
                          ri!archivo,
                          "folio",
                          null
                        ),
                        ".csv"
                      ),
                      mensajeRespuesta: local!mensajeRespuesta,
                      intentoDescarga: local!intentoDescarga,
                      consultaDoc: local!consultaDoc
                    ),
                    /*Agregado para  descarga asincrona bloque*/
                    #"SYSTEM_SYSRULES_columnsLayout"(
                      columns: {
                        #"SYSTEM_SYSRULES_columnLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                              buttons: {
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Archivo de Respuesta", 
                                  size: "SMALL",
                                  style: "SOLID",
                                  color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774",
                                  submit: false,
                                  value:true,
                                  saveInto:{
                                    a!save(local!showGenerarArchivo,save!value),
                                  },
                                  disabled:if(or(ri!archivo.subproceso.id==118,ri!archivo.subproceso.id==120,ri!archivo.subproceso.id==122),false,true),
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "GENERACIÓN DE MOVIMIENTOS",
                                  value: true,
                                  saveInto: {

                                    /* Consulta cuentas no marcadas */
                                    a!save(
                                      local!brandsCoexistence,
                                      #"1a05f799-cf19-4ce1-90d5-aaf772921e48"(
                                        folioNumber: index(ri!archivo, "folio", null),
                                        brandStatus: 0,
                                        page: 1,
                                        limit: 10
                                      ).result.headers
                                    ),
                                    a!save(
                                      local!reloadBrands,
                                      not(local!reloadBrands)
                                    ),

                                    /* Evaluación principal */
                                    if(
                                      and(
                                        a!isNotNullOrEmpty(
                                          index(local!brandsCoexistence, "totalrecords", null)
                                        ),
                                        toInteger(index(local!brandsCoexistence, "totalrecords", 0)) > 0
                                      ),

                                      /* Hay cuentas */
                                      if(
                                        and(
                                          toInteger(index(local!brandsCoexistence, "totalrecords", 0)) > 0,
                                          toInteger(index(local!brandsCoexistence, "totalrecords", 0)) < 150
                                        ),

                                        /* CASO 1 y 2 */
                                        {
                                          a!save(
                                            local!messageCoexistence,
                                            "Debe exportar el reporte porque existe(n) " &
                                            index(local!brandsCoexistence, "totalrecords", 0) &
                                            " cuenta(s) individual(es) no marcada(s)."
                                          ),

                                          a!save(
                                            local!activeMarcas,
                                            not(local!activeMarcas)
                                          ),
                                          a!save(
                                            local!flagExportarCuentas,
                                            true
                                          )

                                        },

                                        /* CASO > 150 */
                                        if(
                                          toInteger(index(local!brandsCoexistence, "totalrecords", 0)) > 150,
                                          {
                                            a!save(
                                              local!messageCoexistence,
                                              "Se ha excedido la cantidad de cuentas individuales no marcadas por lo que debe solicitar la información al área de Soporte a Producción."
                                            ),
                                            a!save(
                                              local!activeMarcas,
                                              not(local!activeMarcas)
                                            )
                                          },
                                          {}
                                        )
                                      ),

                                      /* CASO 0 registros */
                                      a!save(local!showCalcMovs, save!value)
                                    )
                                  },
                                  submit: false,
                                  size: "SMALL",
                                  style: "SOLID",
                                  color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774",
                                  loadingIndicator: true
                                ),

                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Rechazar Folio",
                                  saveInto: a!save(local!vistaModalRechazarFolio, true),
                                  size: "SMALL",
                                  style: "SOLID",
                                  color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_34909",

                                ),

                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: if(and(local!intentoDescarga,local!mensajeRespuesta="Incompleto"),if(a!isNullOrEmpty(local!consultaDoc),"Descargando Excel","Documento Disponible"),"Exportar Excel"),
                                  /*Agregado para  descarga asincrona*/
                                  icon: if(and(local!intentoDescarga,local!mensajeRespuesta="Incompleto"),if(a!isNullOrEmpty(local!consultaDoc),"spinner-alt","file-export"),null),
                                  value: true,
                                  saveInto: {
                                    a!save(local!docId_int, null),
                                    #"SYSTEM_SYSRULES_startProcess3"(
                                      processModel: #"_a-0000ee45-8509-8000-9bb1-011c48011c48_330655",
                                      processParameters: {
                                        /*Agregado para  descarga asincrona*/
                                        idInstancia: ri!request.idInstancia,
                                        user:loggedInUser(),
                                        inputService:a!map(
                                          /*Agregado para  descarga asincrona*/
                                          folioRequerido: ri!archivo.folio,
                                          folioNumber: ri!archivo.folio,
                                          preNumbers: false
                                        ),
                                        option:7
                                      },
                                      isSynchronous: true,
                                      onSuccess:{
                                        a!save(
                                          local!docId_int,
                                          index(fv!processInfo.pv,"document",null)
                                        ),
                                        a!save(
                                          local!mensajeRespuesta,
                                          index(fv!processInfo.pv, "mensajeRespuesta", null),
                                        ),
                                        a!save(local!nombreDocumento, "Cifras_Control_")
                                      },
                                      /*Agregado para  descarga asincrona bloque*/
                                      onIncomplete: {

                                        a!save(
                                          local!mensajeRespuesta,
                                          "Incompleto",

                                        )
                                      }
                                      /*Agregado para  descarga asincrona bloque*/
                                    ),
                                    a!save(local!show, true),
                                    a!save(local!intentoDescarga, true),
                                  },
                                  style: "SOLID",
                                  color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_34909",
                                  size: "SMALL",
                                  submit: false,
                                  /*Agregado para  descarga asincrona*/
                                  disabled: if(and(local!intentoDescarga,local!mensajeRespuesta="Incompleto"),true,false),
                                  /*disabled: a!isNullOrEmpty(ri!selectedProcessId),*/
                                  loadingIndicator: true,
                                  showWhen: true
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "EXPORTAR CUENTAS DESMARCADAS",
                                  value: true,
                                  saveInto: {
                                    a!save(local!docId_int, null),
                                    #"SYSTEM_SYSRULES_startProcess3"(
                                      processModel: #"_a-0000ee45-8509-8000-9bb1-011c48011c48_330655",
                                      processParameters: {
                                        user: loggedInUser(),
                                        inputService: a!map(
                                          lstFolios: ri!archivo.folio
                                        ),
                                        option: 23
                                      },
                                      isSynchronous: true,
                                      onSuccess: {
                                        a!save(
                                          local!docId_int,
                                          index(fv!processInfo.pv, "document", null)
                                        ),
                                        a!save(
                                          local!mensajeRespuesta,
                                          index(fv!processInfo.pv, "mensajeRespuesta", null)
                                        ),
                                        a!save(local!intentoDescarga, true),
                                        a!save(local!nombreDocumento, "Cuentas_Desmarcadas_")
                                      }
                                    ),
                                    a!save(local!show, true),
                                    a!save(local!intentoDescarga, true),
                                  },
                                  style: "SOLID",
                                  color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_34909",
                                  size: "SMALL",
                                  submit: false,
                                  loadingIndicator: true,
                                  showWhen: local!flagExportarCuentas
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
